#include "pe_state_graph_archive.h"
#include "pe_state_actor_prepare.h"
#include <string.h>
#include <stdint.h>
static uint32_t get32(const unsigned char*p){return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static uint64_t get64(const unsigned char*p){return(uint64_t)get32(p)|(uint64_t)get32(p+4)<<32;}
typedef struct GraphChunks{const unsigned char*world,*render,*battle;size_t worldBytes,renderBytes,battleBytes;}GraphChunks;
static int chunks(const PeStateIdentity*identity,const unsigned char*in,size_t bytes,GraphChunks*out){PeStateInfo info;int r=PeState_Inspect(in,bytes,identity,&info);if(r)return r;if(info.kind!=PE_STATE_PARTIAL)return PE_STATE_INCOMPLETE;memset(out,0,sizeof*out);size_t at=PE_STATE_HEADER_BYTES;for(unsigned i=0;i<info.count;i++){uint32_t id=get32(in+at),n=get32(in+at+8);if(id==PE_STATE_SCENE){out->world=in+at+16;out->worldBytes=n;}if(id==PE_STATE_ACTORS){out->render=in+at+16;out->renderBytes=n;}if(id==PE_STATE_BATTLE){out->battle=in+at+16;out->battleBytes=n;}at+=16+n;}return out->worldBytes>=28&&out->battleBytes>=28&&out->render?0:PE_STATE_INCOMPLETE;}
static int matches(const PeWorldState*w,const PeBattleNumeric*b,const GraphChunks*c){return get64(c->world+4)==w->session&&get64(c->world+12)==w->scene&&get64(c->world+20)==w->binding&&get64(c->battle+4)==b->session&&get64(c->battle+12)==b->scene&&get64(c->battle+20)==b->binding&&w->session==b->session&&w->scene==b->scene&&w->assetGeneration==b->assetGeneration&&w->serialCounter==b->entitySerialCounter&&w->liveCount==b->entityLiveCount;}
static int valid(PeWorldState*w,PeBattleNumeric*b,const GraphChunks*c){uint32_t roles[14]={0};if(!matches(w,b,c)||!PeStateActor_PreflightGraph(w,c->world,c->worldBytes,c->render,c->renderBytes))return 0;for(unsigned i=0;i<14;i++)if(w->liveMask&(1u<<i))roles[i]=w->actor[i].coreRole;return PeBattleNumeric_PreflightTarget(b,c->battle,c->battleBytes,w->liveMask,roles);}
void PeStateGraphArchive_Init(PeStateGraphArchive*a){if(a)memset(a,0,sizeof*a);}
int PeStateGraphArchive_Remember(PeStateGraphArchive*a,const PeWorldState*w,const PeBattleNumeric*b,const PeStateIdentity*identity,const unsigned char*in,size_t bytes){if(!a||!w||!b||a->serial==UINT64_MAX||!PeWorld_IsCurrent(w)||!PeBattleNumeric_IsCurrent(b))return PE_STATE_INCOMPATIBLE;GraphChunks c;int r=chunks(identity,in,bytes,&c);if(r)return r;PeWorldState wc=*w;PeBattleNumeric bc=*b;if(!valid(&wc,&bc,&c))return PE_STATE_INCOMPATIBLE;unsigned slot=0;for(unsigned i=0;i<PE_STATE_GRAPH_ARCHIVE_SLOTS;i++){if(a->slots[i].serial&&matches(&a->slots[i].world,&a->slots[i].battle,&c)){slot=i;break;}if(a->slots[i].serial<a->slots[slot].serial)slot=i;}wc.targetMode=0;bc.targetMode=0;a->slots[slot]=(PeStateGraphRecord){++a->serial,wc,bc};return 0;}
int PeStateGraphArchive_Select(const PeStateGraphArchive*a,const PeStateIdentity*identity,const unsigned char*in,size_t bytes,PeWorldState*w,PeBattleNumeric*b){if(!a||!w||!b)return PE_STATE_INVALID;GraphChunks c;int r=chunks(identity,in,bytes,&c);if(r)return r;for(unsigned i=0;i<PE_STATE_GRAPH_ARCHIVE_SLOTS;i++){const PeStateGraphRecord*s=&a->slots[i];if(s->serial&&matches(&s->world,&s->battle,&c)){PeWorldState wc=s->world;PeBattleNumeric bc=s->battle;if(!valid(&wc,&bc,&c))return PE_STATE_INCOMPATIBLE;*w=wc;*b=bc;return 0;}}return PE_STATE_INCOMPATIBLE;}
